var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City not loaded"); return; }
var roots = scene.GetRootGameObjects();

Sim.PhoneControllerUI phone = null;
SettingsUI settings = null;
TMPro.TMP_InputField sourceInput = null;
PhoneApplicationButton settingsBtn = null;
foreach (var r in roots) {
    if (phone == null) phone = r.GetComponentInChildren<Sim.PhoneControllerUI>(true);
    if (settings == null) settings = r.GetComponentInChildren<SettingsUI>(true);
    foreach (var f in r.GetComponentsInChildren<TMPro.TMP_InputField>(true)) {
        if (f.transform.name == "Search Input Field") { sourceInput = f; break; }
    }
    foreach (var b in r.GetComponentsInChildren<PhoneApplicationButton>(true)) {
        if (b.transform.name == "Settings") { settingsBtn = b; break; }
    }
}
if (phone == null || settings == null || sourceInput == null || settingsBtn == null) {
    Debug.LogError("Missing refs: phone=" + (phone!=null) + " settings=" + (settings!=null) + " input=" + (sourceInput!=null) + " btn=" + (settingsBtn!=null));
    return;
}

// 1) Clone Settings GO as Support sibling under Phone
var supportGO = UnityEngine.Object.Instantiate(settings.gameObject, settings.transform.parent);
supportGO.name = "Support";

// Replace SettingsUI -> SupportUI
var oldSettings = supportGO.GetComponent<SettingsUI>();
if (oldSettings != null) UnityEngine.Object.DestroyImmediate(oldSettings, true);
var supportUI = supportGO.AddComponent<SupportUI>();

// 2) Update Brand text
var brandTr = supportGO.transform.Find("Brand");
if (brandTr != null) {
    var brandTxt = brandTr.GetComponent<TMPro.TextMeshProUGUI>();
    if (brandTxt != null) brandTxt.text = "Support";
}

// 3) Strip Active View children, keep only Save + Result
var activeView = supportGO.transform.Find("Active View");
UnityEngine.Transform keepSave = null;
UnityEngine.Transform keepResult = null;
for (int i = activeView.childCount - 1; i >= 0; i--) {
    var child = activeView.GetChild(i);
    if (child.name == "Save")        { keepSave = child;   continue; }
    if (child.name == "Result")      { keepResult = child; continue; }
    UnityEngine.Object.DestroyImmediate(child.gameObject, true);
}

// 4) Clone the search input as the message field, place it before Save/Result
var inputGO = UnityEngine.Object.Instantiate(sourceInput.gameObject, activeView);
inputGO.name = "Message Input";
inputGO.transform.SetSiblingIndex(0);
var msgInput = inputGO.GetComponent<TMPro.TMP_InputField>();
msgInput.text = string.Empty;
msgInput.lineType = TMPro.TMP_InputField.LineType.MultiLineNewline;
msgInput.characterLimit = 500;
if (msgInput.placeholder is TMPro.TextMeshProUGUI ph) ph.text = "Décris ton problème ici…";
var inputRT = (UnityEngine.RectTransform)inputGO.transform;
inputRT.sizeDelta = new UnityEngine.Vector2(inputRT.sizeDelta.x, 200f);

// 5) Update Save button text
if (keepSave != null) {
    var saveTxt = keepSave.GetComponentInChildren<TMPro.TextMeshProUGUI>(true);
    if (saveTxt != null) saveTxt.text = "Envoyer";
}

// 6) Clear any onClick listeners inherited from Settings clone — we'll wire SupportUI ourselves
var saveBtn = keepSave != null ? keepSave.GetComponent<UnityEngine.UI.Button>() : null;
if (saveBtn != null) saveBtn.onClick.RemoveAllListeners();
var resultTxt = keepResult != null ? keepResult.GetComponent<TMPro.TextMeshProUGUI>() : null;
if (resultTxt != null) resultTxt.text = string.Empty;

// 7) Wire SupportUI serialized fields
var soSupport = new UnityEditor.SerializedObject(supportUI);
soSupport.Update();
soSupport.FindProperty("messageField").objectReferenceValue = msgInput;
soSupport.FindProperty("submitButton").objectReferenceValue = saveBtn;
soSupport.FindProperty("feedbackText").objectReferenceValue = resultTxt;
soSupport.ApplyModifiedProperties();

// 8) Hide the panel by default (Settings is inactive in the scene)
supportGO.SetActive(false);

// 9) Clone the Settings home button as Support button under Application Container
var supportBtnGO = UnityEngine.Object.Instantiate(settingsBtn.gameObject, settingsBtn.transform.parent);
supportBtnGO.name = "Support";
var supportBtn = supportBtnGO.GetComponent<PhoneApplicationButton>();
// Wire button.application -> SupportUI
var soBtn = new UnityEditor.SerializedObject(supportBtn);
soBtn.Update();
var appProp = soBtn.FindProperty("application");
if (appProp != null) appProp.objectReferenceValue = supportUI;
soBtn.ApplyModifiedProperties();

// Try to update the icon label TMP text if any (visible button label)
foreach (var tmp in supportBtnGO.GetComponentsInChildren<TMPro.TextMeshProUGUI>(true)) {
    string lower = tmp.text != null ? tmp.text.ToLower() : "";
    if (lower.Contains("settings") || lower.Contains("réglage") || lower.Contains("reglage") || lower.Contains("paramètre")) {
        tmp.text = "Support";
    }
}

UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
Debug.Log("[Support] Created Support GO iid=" + supportGO.GetInstanceID() + " Btn iid=" + supportBtnGO.GetInstanceID() + " — scene saved.");
